1: function getPermutation(n, k) {
2:   let nums = [1, 2, ..., n];
3:   let fact = [1, 1, 2, 6, ...];
4:   k = k - 1;
5:   let res = '';
6:   for (let i = n; i > 0; i--) {
7:     let idx = Math.floor(k / fact[i - 1]);
8:     res += nums.splice(idx, 1);
9:     k %= fact[i - 1];
10:  }
11:  return res;
12: }
